const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

// 1. Authenticate Webhook Secret
const expectedSecret = "cf7_lab_secret_token_12345";
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];

if (!providedSecret || providedSecret !== expectedSecret) {
    return [{
        json: {
            auth_ok: false,
            status_code: 401,
            error: "Unauthorized: Invalid or missing X-Webhook-Secret header"
        }
    }];
}

// 2. Validate Schema & Required Fields
const required = ['submission_id', 'full_name', 'email', 'service_required', 'message'];
const missing = [];
for (const field of required) {
    if (!body[field] || String(body[field]).trim() === '') {
        missing.push(field);
    }
}

if (missing.length > 0) {
    return [{
        json: {
            auth_ok: true,
            valid_schema: false,
            status_code: 400,
            error: `Bad Request: Missing required field(s): ${missing.join(', ')}`
        }
    }];
}

// 3. Email Format Validation
const emailStr = String(body.email).trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(emailStr)) {
    return [{
        json: {
            auth_ok: true,
            valid_schema: false,
            status_code: 400,
            error: "Bad Request: Invalid email format"
        }
    }];
}

// 4. Data Normalization
const normalized = {
    submission_id: String(body.submission_id).trim(),
    full_name: String(body.full_name).trim(),
    email: emailStr,
    phone: body.phone ? String(body.phone).trim() : null,
    company: body.company ? String(body.company).trim() : null,
    service_required: String(body.service_required).trim(),
    message: String(body.message).trim(),
    source_form_id: body.source_form_id || null,
    received_at: new Date().toISOString()
};

return [{
    json: {
        auth_ok: true,
        valid_schema: true,
        status_code: 200,
        lead: normalized
    }
}];

